    check = set()
    for x in range(1, modulus):
        if x ** 2 - coefficient1 * x + coefficient2 == 0:
            check.add(x)
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'modulus': modulus, 'coefficient1': coefficient1, 'coefficient2': coefficient2}
    return (parameters, answer, check)



